SELECT *, RANK() OVER (PARTITION BY product_id, order_id ORDER BY quantity ASC NULLS FIRST) AS quantity_rank, SUM(unit_price) OVER (PARTITION BY order_id, product_id ORDER BY unit_price ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_unit_price, AVG(quantity) OVER (ORDER BY unit_price ASC, id ASC ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS quantity_avg_5 FROM order_items;
